	@ParameterizedTest
	@CsvSource({ "2,false", "3,false", "2,true", "3,true" })
	void failedFamilyAdmissionReturnsEveryLeaseAndCanBeRetried(int failedMember, boolean reserved) throws Exception {
		List<Quad> expected = List.of(new Quad(10, 20, 30, 7, true));
		try (TripleStore store = newStore()) {
			write(store, expected);
			TxnManager manager = store.getTxnManager();
			int slots = manager.availableReadTxnSlots(100, 1);
			AtomicInteger admissions = new AtomicInteger();
			IllegalStateException injected = new IllegalStateException("injected partial metadata family admission");
			manager.setAdmissionObserverForTest(reader -> {
				if (admissions.incrementAndGet() == failedMember) {
					throw injected;
				}
			});
			try {
				assertThat(assertThrows(IllegalStateException.class, () -> openFamily(store, reserved)))
						.isSameAs(injected);
			} finally {
				manager.setAdmissionObserverForTest(null);
			}
			assertThat(admissions).hasValue(failedMember);
			assertThat(manager.availableReadTxnSlots(100, 1)).isEqualTo(slots);
			assertThat(manager.activeOrdinaryReaderSnapshotForTest()).isEmpty();
			Txn[] retried = openFamily(store, reserved);
			try {
				for (Txn member : retried) {
					assertModel(store, member, expected);
				}
			} finally {
				for (Txn member : retried) {
					member.close();
				}
			}
			assertThat(manager.availableReadTxnSlots(100, 1)).isEqualTo(slots);
		}
	}

