	private static Txn[] openFamily(TripleStore store, boolean reserved) throws Exception {
		if (!reserved) {
			return store.getTxnManager().createReadTxnPinnedFamily(3, store::getDataRevision);
		}
		try (TxnManager.ReaderReservation reservation = store.getTxnManager().reserveReadTxnPinnedFamily(3)) {
			return reservation.openPinnedFamily(store::getDataRevision);
		}
	}

	@Test
	void boundedPrefixCheckpointRebasesOnlyTheOldestSegmentsWithoutChangingOldReaders() throws Exception {
		List<Quad> first = distinctQuads(0, 256);
		List<Quad> second = distinctQuads(256, 256);
		List<Quad> third = distinctQuads(512, 1);
		try (TripleStore store = newStore()) {
			store.startTransaction();
			int metadata = LmdbPersistentAdjacency.openExisting(store.writeTxn).metadataDbi();
			for (Quad quad : first) {
				store.storeTriple(quad.subject, quad.predicate, quad.object, quad.context, quad.explicit);
			}
			store.commit();
			try (Txn oldest = store.getTxnManager().createReadTxnPinned(store::getDataRevision)) {
				write(store, second);
				try (Txn beforeCheckpoint = store.getTxnManager().createReadTxnPinned(store::getDataRevision)) {
					assertThat(rawExplicitTotal(beforeCheckpoint.get(), metadata)).isZero();
					long revision = store.getDataRevision();
					assertThat(store.checkpointMetadata(4096)).isPositive().isLessThanOrEqualTo(4096);
					assertThat(store.getDataRevision()).as("metadata maintenance does not change statement revision")
							.isEqualTo(revision);
					try (Txn current = store.getTxnManager().createReadTxn()) {
						assertThat(rawExplicitTotal(current.get(), metadata)).as("only the oldest segment was folded")
								.isEqualTo(first.size());
						assertModel(store, current, union(first, second));
						assertThat(manifest(current).clean()).as("a suffix remains after partial checkpoint").isFalse();
					}
					assertThat(rawExplicitTotal(oldest.get(), metadata)).isZero();
					assertThat(rawExplicitTotal(beforeCheckpoint.get(), metadata)).isZero();
					assertModel(store, oldest, first);
					assertModel(store, beforeCheckpoint, union(first, second));
					write(store, third);
					assertThat(store.checkpointMetadata(4096)).isPositive().isLessThanOrEqualTo(4096);
					try (Txn current = store.getTxnManager().createReadTxn()) {
						assertModel(store, current, union(union(first, second), third));
						assertThat(rawExplicitTotal(current.get(), metadata)).isEqualTo(513);
						assertThat(manifest(current).clean()).isTrue();
					}
					assertThat(store.checkpointMetadata(4096)).as("all committed segments have been folded").isZero();
					assertModel(store, oldest, first);
					assertModel(store, beforeCheckpoint, union(first, second));
				}
			}
		}
	}

